<?phpinclude_once('db.php');/** @var TYPE_NAME $host *//** @var TYPE_NAME $username *//** @var TYPE_NAME $pass *//** @var TYPE_NAME $dbName */$con = new mysqli($host, $username, $pass, $dbName);if(isset($_POST['getEventCamp'])){    $response= new stdClass();    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $campus=$_POST['campus'];        $eventType=$_POST['eventType'];        $query="SELECT        researchallfile.author,       researchfile.campus,       researchallfile.researchfile ,       researchfile.categoryFROM researchallfileJOIN researchfile ON researchallfile.docid=researchfile.idWHERE researchfile.campus=? AND researchallfile.eventType=?";        $statement=$con->prepare($query);        $statement->bind_param("ss",$campus,$eventType);    }}if(isset($_POST['backup'])){    $response= new stdClass();    $response->campus=[];    if ($con = new mysqli($host, $username, $pass, $dbName)) {        $eventNamePost=$_POST['eventName'];        $query1="SELECT researchfile.campus FROM researchallfile RIGHT JOIN researchfile ON researchallfile.docid=researchfile.id WHERE researchfile.event=? GROUP BY researchfile.campus";        $statement=$con->prepare($query1);        $statement->bind_param("s",$eventNamePost);        $statement->execute();        $res=$statement->get_result();        while ($row = $res->fetch_assoc()){            $perCamp= new stdClass();            $perCamp->campusName=$row['campus'];            $perCamp->campusFiles=[];            $query2="SELECT endorsement.file,endorsement.id FROM researchallfile LEFT JOIN researchfile ON researchallfile.docid=researchfile.idLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE endorsement.campus=? ";            $statement2=$con->prepare($query2);            $statement2->bind_param('s',$row['campus']);            $statement2->execute();            $res2=$statement2->get_result();            while ($row2 = $res2->fetch_assoc()){                $endorsement=new stdClass();                $endorsement->endorsementFile=$row2['file'];                $endorsement->entries=[];                $query3="SELECT researchfile.category FROM researchallfile LEFT JOIN researchfile ON researchallfile.docid=researchfile.idWHERE researchfile.endorsementid=? Group BY researchfile.category";                $statement3=$con->prepare($query3);                $statement3->bind_param('s',$row2['id']);                $statement3->execute();                $res3=$statement3->get_result();                while ($row3=$res3->fetch_assoc()){                    $entries=new stdClass();                    $entries->category=$row3['category'];                    $entries->filesDocs=[];                    $query4="SELECT  researchallfile.researchfile,researchallfile.author,researchallfile.docid FROM researchallfile LEFT JOIN researchfile ON researchallfile.docid=researchfile.idLEFT JOIN endorsement ON researchfile.endorsementid=endorsement.idWHERE researchfile.category=?AND researchfile.endorsementid=?AND researchallfile.eventType=?AND researchfile.campus=?";                    $statement4=$con->prepare($query4);                    $statement4->bind_param('ssss',$row3['category'],$row2['id'],$eventNamePost,$row['campus']);                    $statement4->execute();                    $res4=$statement4->get_result();                    while ($row4=$res4->fetch_assoc()){                        $resEntry=NEW stdClass();                        $resEntry->file=$row4['researchfile'];                        $resEntry->docId=$row4['docid'];                        $resEntry->author=$row4['author'];                        $entries->filesDocs[]=$resEntry;                    }                    $endorsement->entries[]=$entries;                }                $perCamp->campusFiles[]=$endorsement;            }            $response->campus[]=$perCamp;        }    }    echo json_encode($response);}